import type { AIToolbarContextValue } from "../ai-toolbar.types";

import { createContext, useContext } from "react";

export const AIToolbarContext = createContext<AIToolbarContextValue | undefined>(undefined);

export const useAIToolbar = () => {
  const context = useContext(AIToolbarContext);
  if (!context) {
    throw new Error("useAIToolbar must be used within an AIToolbar component");
  }
  return context;
};
